import type { Element } from './elements';
import { POKEDEX_SPECIES } from '../content/pokedex';

// Species model. The survivor game's roster is the Pokémon in src/content/pokedex.ts,
// generated by scripts/build-content.mjs from PokéAPI (data), PMD SpriteCollab (sprites,
// portraits) and PokeAPI/cries, with gameplay roles from content/roster.json.

export interface Stats { hp: number; atk: number; def: number; spa: number; spd: number; spe: number }

export type BossAttack = 'charge' | 'slam' | 'radial' | 'spiral' | 'summon' | 'volley' | 'boulder';
export type Behaviour = 'chase' | 'ranged' | 'charger' | 'swarm' | 'healer' | 'tank';

export interface SpeciesDef {
  id: string;
  name: string;
  elements: Element[];
  stats: Stats;
  height: number; // world height of the sprite (m)
  flying?: boolean; // glide (player) / float over terrain (enemy)
  art: string;
  dex?: number; // national Pokédex number
  types?: string[]; // official type names, for display
  scale?: number; // integer sprite scale (bosses are drawn 2-4x)
  // player-only
  playable?: boolean;
  blurb?: string;
  starter?: string; // starting move key
  learnset?: [number, string][]; // [game level, moveKey] (curated in content/roster.json)
  /** the line's other canonical level-up attacks [canonical level, key], offered rarely as coverage */
  coverage?: [number, string][];
  evolvesTo?: string;
  evolveLevel?: number; // game evolution level
  /** canonical source facts (PokéAPI, HGSS version group), kept apart from game balancing */
  canon?: { versionGroup: string; levelUp: [number, string][]; abilities: string[]; heightM: number; weightKg: number; evolveLevel?: number; evolveTrigger?: string };
  ability?: string; // legacy originals only ('adaptive'); Pokémon abilities come from canon.abilities
  // enemy-only
  behaviour?: Behaviour;
  shot?: Element; // ranged projectile element
  boss?: { attacks: BossAttack[]; phaseHp: number[]; summon?: string; title: string };
}

export const bst = (s: Stats) => s.hp + s.atk + s.def + s.spa + s.spd + s.spe;

export const SPECIES: SpeciesDef[] = POKEDEX_SPECIES;

export const SPECIES_BY_ID: Record<string, SpeciesDef> = Object.fromEntries(SPECIES.map((s) => [s.id, s]));

/** Weight class 0-4 from PokéAPI kilograms: Weightless < 1 kg, Light < 10, Medium < 50, Heavy < 200, Massive.
 *  Bosses count one class heavier. It decides what a Pokémon can Guard against and what can move it. */
export function weightClass(sp: SpeciesDef, boss = false): number {
  const kg = sp.canon?.weightKg ?? 20;
  const c = kg < 1 ? 0 : kg < 10 ? 1 : kg < 50 ? 2 : kg < 200 ? 3 : 4;
  return Math.min(4, c + (boss ? 1 : 0));
}
export const WEIGHT_NAMES = ['Weightless', 'Light', 'Medium', 'Heavy', 'Massive'] as const;
